cd /tmp && cat > pty2.py <<'PY'
import os, select
BASE = {'PATH':'/usr/bin:/bin','HOME':'/tmp'}
def run_pty(args, stdin_data=None, env=None, tty_out=True):
    m, s = os.openpty()
    e = dict(BASE)
    if env: e.update(env)
    if stdin_data is not None:
        r, w = os.pipe()
        os.write(w, stdin_data.encode()); os.close(w)
    pid = os.fork()
    if pid == 0:
        if stdin_data is not None: os.dup2(r,0)
        else: os.dup2(s,0)
        os.dup2(s,1); os.dup2(s,2); os.close(m); os.close(s)
        os.execvpe(args[0], args, e); os._exit(1)
    if stdin_data is not None: os.close(r)
    os.close(s)
    out=b''
    while True:
        try:
            rl,_,_ = select.select([m],[],[],2.0)
            if not rl: break
            d = os.read(m, 65536)
            if not d: break
            out += d
        except OSError: break
    os.waitpid(pid,0); os.close(m)
    return out
